-- Phases 6-7 — payouts, transactions, settings and security alerts.
--
-- RECOVERY MIGRATION. These four models were added to schema.prisma and
-- applied to the development database directly (`prisma db push`), which
-- creates tables but writes no migration. The result: dev worked, while a
-- fresh `prisma migrate deploy` — CI, staging, production — produced a
-- database with none of these tables, and every payouts/settings/dashboard
-- route would have failed at runtime.
--
-- Generated by diffing the migration history against schema.prisma, so it
-- reproduces exactly the state dev already had.

CREATE TYPE "PayoutStatus" AS ENUM ('PENDING', 'PENDING_REVIEW', 'APPROVED', 'PROCESSING', 'PAID', 'FAILED', 'CANCELLED');

-- CreateEnum
CREATE TYPE "PayoutMethod" AS ENUM ('STRIPE_CONNECT', 'MANUAL');

-- CreateEnum
CREATE TYPE "TransactionType" AS ENUM ('DEPOSIT', 'WITHDRAWAL', 'ENTRY_FEE', 'PRIZE', 'ADJUSTMENT', 'REFUND');

-- CreateEnum
CREATE TYPE "TransactionStatus" AS ENUM ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED');

-- CreateEnum
CREATE TYPE "StripeAccountStatus" AS ENUM ('NOT_CONNECTED', 'PENDING', 'VERIFIED', 'RESTRICTED');

