ALTER TABLE "TournamentRegistration" ADD COLUMN     "payoutId" TEXT;

-- AlterTable
ALTER TABLE "User" ADD COLUMN     "stripeAccountStatus" "StripeAccountStatus" NOT NULL DEFAULT 'NOT_CONNECTED',
ADD COLUMN     "stripeConnectAccountId" TEXT;

